package tw.rex.learningtv;
import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import java.util.*;import org.json.*;import tw.rex.link.Skin;
final class WatchOverlay {
 interface Callback {void correct(JSONObject q,String choice);void wrong(JSONObject q,String choice);void recover(String code);void back();void read(JSONObject q);}
 final Context context;final Callback callback;JSONObject q;boolean finished=false;TextView feedback;ArrayList<String> choices=new ArrayList<String>();
 WatchOverlay(Context c,Callback cb){context=c;callback=cb;}
 int dp(int n){return (int)(n*context.getResources().getDisplayMetrics().density);}
 TextView text(String s,int size){TextView t=new TextView(context);t.setText(s);Skin.text(t);t.setTextSize(size);t.setPadding(dp(8),dp(4),dp(8),dp(4));return t;}
 GradientDrawable background(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(10));return d;}
 Button button(String s){Button b=Skin.button(context,s,Math.abs(s.hashCode()%3));b.setTextSize(22);return b;}
 View create(JSONObject question,int seconds){q=question;LinearLayout box=new LinearLayout(context);box.setOrientation(1);box.setPadding(dp(40),dp(18),dp(40),dp(18));box.setGravity(Gravity.CENTER_VERTICAL);Skin.card(box);box.addView(text("答對一題，就能繼續看 "+seconds+" 秒",26));if(q.optString("topic").equals("logic"))box.addView(text(tw.rex.link.QuestionCatalog.label(q),17));box.addView(text(q.optString("question"),29));JSONArray opts=q.optJSONArray("options");for(int i=0;i<opts.length();i++)choices.add(opts.optString(i));Collections.shuffle(choices);ArrayList<Button> buttons=new ArrayList<Button>();for(int i=0;i<choices.size();i++){final String choice=choices.get(i);Button b=button((char)('A'+i)+"   "+choice);LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(-1,dp(52));params.setMargins(0,dp(5),0,dp(5));box.addView(b,params);buttons.add(b);b.setOnClickListener(v->{if(finished)return;if(tw.rex.link.WatchRules.grantsReward(q.optString("answer"),choice,finished,false)){finished=true;for(Button item:buttons)item.setEnabled(false);callback.correct(q,choice);}else{feedback.setText("再想一想，答對才可以繼續看電視。");callback.wrong(q,choice);b.setEnabled(false);for(Button item:buttons)if(item.isEnabled()){item.requestFocus();break;}}});}feedback=text("用遙控器方向鍵選答案，按 OK 確認。",18);box.addView(feedback);
 Button read=button("再唸一次");read.setTextSize(16);box.addView(read,new LinearLayout.LayoutParams(-2,dp(42)));read.setOnClickListener(v->callback.read(q));Button change=button("換皮膚 · "+Skin.name(context));change.setTextSize(14);box.addView(change,new LinearLayout.LayoutParams(-2,dp(42)));change.setOnClickListener(v->Skin.picker(context,Skin.id(context),id->Skin.set(context,id)));Button recovery=button("家長緊急復原");recovery.setTextSize(14);box.addView(recovery,new LinearLayout.LayoutParams(-2,dp(42)));recovery.setOnClickListener(v->{box.removeAllViews();box.addView(text("家長緊急復原 · 需先前保存的復原碼",24));EditText input=new EditText(context);input.setTextColor(Skin.ink(context));input.setInputType(129);box.addView(input,new LinearLayout.LayoutParams(-1,dp(52)));Button verify=button("驗證家長復原碼");box.addView(verify);verify.setOnClickListener(w->callback.recover(input.getText().toString()));Button back=button("返回答題");box.addView(back);back.setOnClickListener(w->{callback.back();});input.requestFocus();((android.view.inputmethod.InputMethodManager)context.getSystemService(Context.INPUT_METHOD_SERVICE)).showSoftInput(input,android.view.inputmethod.InputMethodManager.SHOW_IMPLICIT);});box.setFocusableInTouchMode(true);buttons.get(0).requestFocus();FrameLayout wallpaper=new FrameLayout(context);wallpaper.setBackground(Skin.background(context,true));ScrollView scroll=new CuteGuard.QuizScroll(context);scroll.setFillViewport(true);scroll.addView(box);FrameLayout.LayoutParams margins=new FrameLayout.LayoutParams(-1,-1);margins.setMargins(dp(42),dp(18),dp(42),dp(76));wallpaper.addView(scroll,margins);TextView author=text("作者：雷允澤 · v1.3.9",14);author.setBackground(Skin.panel(context));FrameLayout.LayoutParams cp=new FrameLayout.LayoutParams(-2,-2,Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL);cp.bottomMargin=dp(24);wallpaper.addView(author,cp);return wallpaper;}
}
